mkdir -p /tmp/work && cat > /tmp/work/fetch.py <<'EOF'
import json, time, urllib.request, urllib.error, sys
BASE = "http://localhost:8080"
token = None
events = []

def get_token():
    req = urllib.request.Request(BASE + "/token", method="POST")
    with urllib.request.urlopen(req, timeout=30) as r:
        return json.load(r)["token"]

def call(path, auth=True):
    global token
    attempts = 0
    while True:
        attempts += 1
        if attempts > 60:
            raise RuntimeError("giving up on " + path)
        if auth and token is None:
            token = get_token()
        headers = {"Authorization": "Bearer " + token} if auth else {}
        req = urllib.request.Request(BASE + path, headers=headers)
        try:
            with urllib.request.urlopen(req, timeout=30) as r:
                return json.load(r)
        except urllib.error.HTTPError as e:
            body = e.read().decode(errors="replace")
            events.append((path, e.code, e.headers.get("Retry-After"), body[:200]))
            if e.code == 401 and auth:
                token = None
                continue
            if e.code == 429:
                wait = e.headers.get("Retry-After")
                try:
                    secs = float(wait)
                except (TypeError, ValueError):
                    secs = 2.0
                time.sleep(secs + 0.5)
                continue
            if e.code == 404:
                return None
            time.sleep(1.5)
            continue
        except (urllib.error.URLError, TimeoutError, ConnectionError, json.JSONDecodeError) as e:
            events.append((path, "exc", None, repr(e)[:200]))
            time.sleep(1.5)
            continue

orders_seen = {}
dupes = 0
page = 1
pages_fetched = 0
total_pages = None
while True:
    data = call(f"/orders?page={page}")
    pages_fetched += 1
    total_pages = data["total_pages"]
    for it in data["items"]:
        if it["id"] in orders_seen:
            dupes += 1
            if orders_seen[it["id"]] != it:
                events.append(("dupe-differs", it["id"], None, json.dumps([orders_seen[it["id"]], it])[:400]))
        else:
            orders_seen[it["id"]] = it
    if data.get("next") is None or page >= total_pages:
        break
    page += 1

customers = {}
for cid in sorted({o["customer_id"] for o in orders_seen.values()}):
    customers[cid] = call(f"/customers/{cid}")

json.dump({"orders": list(orders_seen.values()), "customers": customers,
           "duplicates": dupes, "pages": pages_fetched, "total_pages": total_pages},
          open("/tmp/work/data.json", "w"))
print("pages", pages_fetched, "total_pages", total_pages, "orders", len(orders_seen),
      "dupes", dupes, "customers", len(customers), "missing customers", sum(1 for v in customers.values() if v is None))
from collections import Counter
print("events", len(events))
for e in events[:30]:
    print(e)
EOF
cd /tmp/work && timeout 900 python3 -I fetch.py

